styl:
.iq-combo-hero-233--brad-full,.iq-combo-hero-233--brad-full-32{border-radius:32px!important}
.iq-combo-hero-233--bgr{background-position:top center;background-repeat:no-repeat;min-height:auto;border-radius:10px;background-size:cover}
.iq-combo-hero-233--bgr-image{background:url({{ bg_image }}) center top no-repeat;background-color:#000;background-size:cover}
.iq-combo-hero-233--logo{float:none;max-width:138px;padding-top:32px;padding-bottom:0}
@media screen and (max-width:600px){.iq-combo-hero-233--logo{margin:0 auto!important}}
.iq-combo-hero-233--date{background-size:cover;border-radius:10px;color:#ff8516;display:inline-block;font-family:Helvetica!important;font-size:24px;font-style:normal;font-weight:700;line-height:36px;padding:4px 12px;background:url(https://fsms.quadcode.com/storage/public/d8/0t/39261bdc700vi72g/bg-orange.png) center no-repeat}
.iq-combo-hero-233--white-title{font-family:Helvetica!important;font-weight:700;font-size:42px;line-height:52px;color:#f9f9f9;word-break:break-word;padding-right:30px}
@media screen and (max-width:600px){.iq-combo-hero-233--white-title{font-size:26px!important;line-height:32px!important}}
.iq-combo-hero-233--white-text{font-family:Helvetica!important;font-style:normal;font-weight:400;font-size:18px;line-height:27px;color:#fff;padding-right:20px}
@media screen and (max-width:600px){.iq-combo-hero-233--white-text{padding-right:0!important}}

/* втянуто из стилей семьи при скоупе — блок больше не зависит от main.styl */
.iq-combo-hero-233--pb16{padding-bottom:16px}
.iq-combo-hero-233--pt16{padding-top:16px}
